WHERE rp.status_transaksi IN ('Sudah Transaksi','Sukses Top up','SPM','SI') 

AND k.id_keluarga NOT IN (SELECT id_keluarga FROM riwayat_bpnt WHERE status_transaksi IN ('Sudah Transaksi','Sukses Top up','SPM','SI'));
